const RequestParser = require('./requestParser');
const ResponseBuilder = require('./responseBuilder');
const XMLBuilder = require('./xmlBuilder');

class SAMLIdentityProvider {
    constructor(config) {
        this.config = config;
        this.responseBuilder = new ResponseBuilder(config);
        this.processedRequestIds = new Map();
    }

    parseAuthnRequest(samlRequest, binding = 'redirect') {
        const xml = RequestParser.decodeSAMLRequest(samlRequest, binding);
        const parsed = RequestParser.parseAuthnRequest(xml);

        if (parsed.issueInstant) {
            const timestampValidation = RequestParser.validateTimestamp(parsed.issueInstant);
            if (!timestampValidation.valid) {
                throw new Error(timestampValidation.message);
            }
        }

        return parsed;
    }

    parseLogoutRequest(samlRequest, binding = 'redirect') {
        const xml = RequestParser.decodeSAMLRequest(samlRequest, binding);
        const parsed = RequestParser.parseLogoutRequest(xml);

        if (parsed.issueInstant) {
            const timestampValidation = RequestParser.validateTimestamp(parsed.issueInstant);
            if (!timestampValidation.valid) {
                throw new Error(timestampValidation.message);
            }
        }

        return parsed;
    }

    validateRequestId(requestId, issueInstant) {
        if (!requestId) {
            return { valid: false, message: 'Missing Request ID' };
        }

        const MAX_AGE = 5 * 60 * 1000;
        const now = Date.now();

        if (issueInstant) {
            const issueTime = new Date(issueInstant).getTime();
            if (isNaN(issueTime)) {
                return { valid: false, message: 'Invalid IssueInstant' };
            }

            if (now - issueTime > MAX_AGE) {
                return { valid: false, message: 'SAML request has expired' };
            }

            if (issueTime > now + 60000) {
                return { valid: false, message: 'SAML request time is invalid' };
            }
        }

        if (this.processedRequestIds.has(requestId)) {
            return { valid: false, message: 'Duplicate SAML request (replay protection)' };
        }

        this.processedRequestIds.set(requestId, now);

        const CLEANUP_AGE = 10 * 60 * 1000;
        for (const [id, timestamp] of this.processedRequestIds.entries()) {
            if (now - timestamp > CLEANUP_AGE) {
                this.processedRequestIds.delete(id);
            }
        }

        return { valid: true };
    }

    createLoginResponse(user, options) {
        const attributes = [
            { name: 'uid', value: String(user.uid || user.id || ''), nameFormat: 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic' },
            { name: 'username', value: String(user.username || ''), nameFormat: 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic' },
            { name: 'email', value: String(user.email || ''), nameFormat: 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic' },
            { name: 'displayName', value: String(user.displayName || user.display_name || user.username || ''), nameFormat: 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic' },
            { name: 'role', value: String(user.role || 'user'), nameFormat: 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic' },
            { name: 'department', value: String(user.department || ''), nameFormat: 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic' }
        ];

        const responseOptions = {
            inResponseTo: options.requestId,
            destination: options.acsUrl || options.destination,
            nameID: user.email || user.username || String(user.id || ''),
            nameIDFormat: options.nameIDFormat || 'urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified',
            attributes: attributes,
            sessionIndex: options.sessionIndex,
            audience: options.entityId || options.audience
        };

        return this.responseBuilder.buildLoginResponse(responseOptions);
    }

    createLogoutResponse(options) {
        return this.responseBuilder.buildLogoutResponse(options);
    }

    getMetadata(options) {
        return this.responseBuilder.buildMetadata(options);
    }

    static encodeResponse(xml) {
        return ResponseBuilder.encodeResponse(xml);
    }

    static decodeRequest(samlRequest, binding = 'redirect') {
        return RequestParser.decodeSAMLRequest(samlRequest, binding);
    }
}

module.exports = SAMLIdentityProvider;

const XMLBuilder = require('./xmlBuilder');
const XMLSigner = require('./xmlSigner');

class ResponseBuilder {
    constructor(config) {
        this.issuer = config.issuer;
        this.certificate = config.certificate;
        this.privateKey = config.privateKey;
        this.signer = new XMLSigner(this.privateKey, this.certificate);
    }

    buildLoginResponse(options) {
        const {
            inResponseTo,
            destination,
            nameID,
            nameIDFormat = 'urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified',
            attributes = [],
            sessionIndex,
            audience
        } = options;

        const responseID = XMLBuilder.generateID();
        const assertionID = XMLBuilder.generateID();
        const issueInstant = XMLBuilder.getCurrentTimestamp();
        const notBefore = issueInstant;
        const notOnOrAfter = XMLBuilder.getFutureTimestamp(5);
        const subjectNotOnOrAfter = XMLBuilder.getFutureTimestamp(5);
        const finalSessionIndex = sessionIndex || XMLBuilder.generateID();

        const responseWithoutAssertion = XMLBuilder.buildResponseWithoutAssertion({
            responseID,
            issueInstant,
            destination,
            issuer: this.issuer,
            inResponseTo,
            statusCode: 'urn:oasis:names:tc:SAML:2.0:status:Success'
        });

        const assertion = XMLBuilder.buildAssertion({
            assertionID,
            issueInstant,
            issuer: this.issuer,
            nameID,
            nameIDFormat,
            recipient: destination,
            audience: audience || destination,
            inResponseTo,
            sessionIndex: finalSessionIndex,
            attributes,
            notBefore,
            notOnOrAfter,
            subjectNotOnOrAfter
        });

        const signedAssertion = this.signer.signAssertion(assertion, assertionID);

        const signedResponse = this.signer.signResponse(
            responseWithoutAssertion,
            responseID,
            signedAssertion
        );

        return signedResponse;
    }

    buildLogoutResponse(options) {
        const {
            inResponseTo,
            destination,
            statusCode = 'urn:oasis:names:tc:SAML:2.0:status:Success'
        } = options;

        const responseID = XMLBuilder.generateID();
        const issueInstant = XMLBuilder.getCurrentTimestamp();

        return XMLBuilder.buildLogoutResponse({
            responseID,
            issueInstant,
            destination,
            issuer: this.issuer,
            inResponseTo,
            statusCode
        });
    }

    buildMetadata(options) {
        const {
            entityID,
            ssoLocation,
            sloLocation,
            nameIDFormats
        } = options;

        return XMLBuilder.buildMetadata({
            entityID: entityID || this.issuer,
            certificate: this.certificate,
            ssoLocation,
            sloLocation,
            nameIDFormats
        });
    }

    static encodeResponse(xml) {
        return Buffer.from(xml, 'utf8').toString('base64');
    }
}

module.exports = ResponseBuilder;

const { SignedXml } = require('xml-crypto');

class XMLSigner {
    constructor(privateKey, certificate) {
        this.privateKey = privateKey;
        this.certificate = certificate;
    }

    signAssertion(assertionXml, assertionID) {
        const xml = assertionXml.replace(/<\?xml[^?]*\?>\s*/g, '');

        const sig = new SignedXml();
        sig.privateKey = this.privateKey;

        sig.addReference({
            xpath: `//*[@ID="${assertionID}"]`,
            transforms: [
                'http://www.w3.org/2000/09/xmldsig#enveloped-signature',
                'http://www.w3.org/2001/10/xml-exc-c14n#'
            ],
            digestAlgorithm: 'http://www.w3.org/2001/04/xmlenc#sha256'
        });

        sig.canonicalizationAlgorithm = 'http://www.w3.org/2001/10/xml-exc-c14n#';
        sig.signatureAlgorithm = 'http://www.w3.org/2001/04/xmldsig-more#rsa-sha256';

        sig.keyInfoProvider = {
            getKeyInfo: () => {
                const certBody = this.certificate
                    .replace(/-----BEGIN CERTIFICATE-----/, '')
                    .replace(/-----END CERTIFICATE-----/, '')
                    .replace(/\s/g, '');

                return '<X509Data><X509Certificate>' + certBody + '</X509Certificate></X509Data>';
            }
        };

        sig.computeSignature(xml, {
            location: { reference: "//*[local-name(.)='Issuer']", action: 'after' }
        });

        return sig.getSignedXml();
    }

    signResponse(responseXml, responseID, signedAssertion) {
        const statusCloseTag = '</samlp:Status>';
        const insertPos = responseXml.indexOf(statusCloseTag);

        if (insertPos === -1) {
            throw new Error('Cannot find Status element');
        }

        const beforeAssertion = responseXml.substring(0, insertPos + statusCloseTag.length);
        const afterAssertion = responseXml.substring(insertPos + statusCloseTag.length);

        return beforeAssertion + signedAssertion + afterAssertion;
    }
}

module.exports = XMLSigner;

const crypto = require('crypto');

class XMLBuilder {
    static escapeXML(str) {
        if (!str) return '';
        return String(str)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&apos;');
    }

    static generateID() {
        return `_${crypto.randomBytes(21).toString('hex')}`;
    }

    static formatDate(date) {
        return date.toISOString();
    }

    static getCurrentTimestamp() {
        return this.formatDate(new Date());
    }

    static getFutureTimestamp(minutes) {
        const date = new Date();
        date.setMinutes(date.getMinutes() + minutes);
        return this.formatDate(date);
    }

    static buildAttributes(attributes) {
        if (!attributes || attributes.length === 0) {
            return '';
        }

        const attributeElements = attributes.map(attr => {
            const values = Array.isArray(attr.value) ? attr.value : [attr.value];
            const attributeValues = values.map(val => 
                '<saml:AttributeValue>' + this.escapeXML(val) + '</saml:AttributeValue>'
            ).join('');

            return '<saml:Attribute Name="' + this.escapeXML(attr.name) + '" NameFormat="' + (attr.nameFormat || 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic') + '">' + attributeValues + '</saml:Attribute>';
        }).join('');

        return '<saml:AttributeStatement>' + attributeElements + '</saml:AttributeStatement>';
    }

    static buildAuthnStatement(authnInstant, sessionIndex) {
        return '<saml:AuthnStatement AuthnInstant="' + authnInstant + '" SessionIndex="' + sessionIndex + '">' +
               '<saml:AuthnContext>' +
               '<saml:AuthnContextClassRef>urn:oasis:names:tc:SAML:2.0:ac:classes:PasswordProtectedTransport</saml:AuthnContextClassRef>' +
               '</saml:AuthnContext>' +
               '</saml:AuthnStatement>';
    }

    static buildAssertion(options) {
        const {
            assertionID,
            issueInstant,
            issuer,
            nameID,
            nameIDFormat,
            recipient,
            audience,
            inResponseTo,
            sessionIndex,
            attributes,
            notBefore,
            notOnOrAfter,
            subjectNotOnOrAfter
        } = options;

        const authnStatement = this.buildAuthnStatement(issueInstant, sessionIndex);
        const attributeStatement = this.buildAttributes(attributes);

        const subjectConfirmationInResponseTo = inResponseTo ? ' InResponseTo="' + inResponseTo + '"' : '';

        const assertion = '<saml:Assertion xmlns:saml="urn:oasis:names:tc:SAML:2.0:assertion" ID="' + assertionID + '" Version="2.0" IssueInstant="' + issueInstant + '">' +
            '<saml:Issuer>' + this.escapeXML(issuer) + '</saml:Issuer>' +
            '<saml:Subject>' +
            '<saml:NameID Format="' + nameIDFormat + '">' + this.escapeXML(nameID) + '</saml:NameID>' +
            '<saml:SubjectConfirmation Method="urn:oasis:names:tc:SAML:2.0:cm:bearer">' +
            '<saml:SubjectConfirmationData NotOnOrAfter="' + subjectNotOnOrAfter + '" Recipient="' + this.escapeXML(recipient) + '"' + subjectConfirmationInResponseTo + '/>' +
            '</saml:SubjectConfirmation>' +
            '</saml:Subject>' +
            '<saml:Conditions NotBefore="' + notBefore + '" NotOnOrAfter="' + notOnOrAfter + '">' +
            '<saml:AudienceRestriction>' +
            '<saml:Audience>' + this.escapeXML(audience) + '</saml:Audience>' +
            '</saml:AudienceRestriction>' +
            '</saml:Conditions>' +
            authnStatement +
            attributeStatement +
            '</saml:Assertion>';

        return assertion;
    }

    static buildResponseWithoutAssertion(options) {
        const {
            responseID,
            issueInstant,
            destination,
            issuer,
            inResponseTo,
            statusCode
        } = options;

        const inResponseToAttr = inResponseTo ? ' InResponseTo="' + inResponseTo + '"' : '';

        const response = '<?xml version="1.0" encoding="UTF-8"?>' +
            '<samlp:Response xmlns:samlp="urn:oasis:names:tc:SAML:2.0:protocol" xmlns:saml="urn:oasis:names:tc:SAML:2.0:assertion" ID="' + responseID + '" Version="2.0" IssueInstant="' + issueInstant + '" Destination="' + this.escapeXML(destination) + '"' + inResponseToAttr + '>' +
            '<saml:Issuer>' + this.escapeXML(issuer) + '</saml:Issuer>' +
            '<samlp:Status>' +
            '<samlp:StatusCode Value="' + statusCode + '"/>' +
            '</samlp:Status>' +
            '</samlp:Response>';

        return response;
    }

    static buildMetadata(options) {
        const {
            entityID,
            certificate,
            ssoLocation,
            sloLocation,
            nameIDFormats
        } = options;

        const certBody = certificate
            .replace(/-----BEGIN CERTIFICATE-----/, '')
            .replace(/-----END CERTIFICATE-----/, '')
            .replace(/\s/g, '');

        const nameIDFormatElements = (nameIDFormats || ['urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified'])
            .map(format => '<md:NameIDFormat>' + format + '</md:NameIDFormat>')
            .join('');

        const metadata = '<?xml version="1.0" encoding="UTF-8"?>' +
            '<md:EntityDescriptor xmlns:md="urn:oasis:names:tc:SAML:2.0:metadata" xmlns:ds="http://www.w3.org/2000/09/xmldsig#" entityID="' + this.escapeXML(entityID) + '">' +
            '<md:IDPSSODescriptor WantAuthnRequestsSigned="false" protocolSupportEnumeration="urn:oasis:names:tc:SAML:2.0:protocol">' +
            '<md:KeyDescriptor use="signing">' +
            '<ds:KeyInfo xmlns:ds="http://www.w3.org/2000/09/xmldsig#">' +
            '<ds:X509Data>' +
            '<ds:X509Certificate>' + certBody + '</ds:X509Certificate>' +
            '</ds:X509Data>' +
            '</ds:KeyInfo>' +
            '</md:KeyDescriptor>' +
            '<md:KeyDescriptor use="encryption">' +
            '<ds:KeyInfo xmlns:ds="http://www.w3.org/2000/09/xmldsig#">' +
            '<ds:X509Data>' +
            '<ds:X509Certificate>' + certBody + '</ds:X509Certificate>' +
            '</ds:X509Data>' +
            '</ds:KeyInfo>' +
            '</md:KeyDescriptor>' +
            nameIDFormatElements +
            '<md:SingleSignOnService Binding="urn:oasis:names:tc:SAML:2.0:bindings:HTTP-Redirect" Location="' + this.escapeXML(ssoLocation) + '"/>' +
            '<md:SingleSignOnService Binding="urn:oasis:names:tc:SAML:2.0:bindings:HTTP-POST" Location="' + this.escapeXML(ssoLocation) + '"/>' +
            '<md:SingleLogoutService Binding="urn:oasis:names:tc:SAML:2.0:bindings:HTTP-Redirect" Location="' + this.escapeXML(sloLocation) + '"/>' +
            '</md:IDPSSODescriptor>' +
            '</md:EntityDescriptor>';

        return metadata;
    }

    static buildLogoutResponse(options) {
        const {
            responseID,
            issueInstant,
            destination,
            issuer,
            inResponseTo,
            statusCode
        } = options;

        const inResponseToAttr = inResponseTo ? ' InResponseTo="' + inResponseTo + '"' : '';
        const destinationAttr = destination ? ' Destination="' + this.escapeXML(destination) + '"' : '';

        const response = '<?xml version="1.0" encoding="UTF-8"?>' +
            '<samlp:LogoutResponse xmlns:samlp="urn:oasis:names:tc:SAML:2.0:protocol" xmlns:saml="urn:oasis:names:tc:SAML:2.0:assertion" ID="' + responseID + '" Version="2.0" IssueInstant="' + issueInstant + '"' + destinationAttr + inResponseToAttr + '>' +
            '<saml:Issuer>' + this.escapeXML(issuer) + '</saml:Issuer>' +
            '<samlp:Status>' +
            '<samlp:StatusCode Value="' + (statusCode || 'urn:oasis:names:tc:SAML:2.0:status:Success') + '"/>' +
            '</samlp:Status>' +
            '</samlp:LogoutResponse>';

from flask import Flask, request, render_template, session, redirect, url_for, render_template_string
import os

from saml2 import SAMLResponseParser, AuthnRequestBuilder
from config import saml_config

app = Flask(__name__)
app.secret_key = os.urandom(24)

SP_ENTITY_ID = saml_config.sp_entity_id
SP_ACS_URL = saml_config.sp_acs_url
IDP_SSO_URL = saml_config.idp_sso_url
IDP_CERT = saml_config.get_idp_cert()

processed_assertion_ids = set()


@app.route('/')
def index():
    if 'email' in session:
        return redirect(url_for('admin'))
    return render_template('index.html', config=saml_config)


@app.route('/saml/login')
def saml_login():
    relay_state = request.args.get('next', '/')

    builder = AuthnRequestBuilder(
        sp_entity_id=SP_ENTITY_ID,
        acs_url=SP_ACS_URL,
        idp_sso_url=IDP_SSO_URL
    )

    redirect_url = builder.get_redirect_url(relay_state=relay_state)

    return redirect(redirect_url)


@app.route('/saml/acs', methods=['POST'])
def saml_acs():
    try:
        saml_response = request.form.get('SAMLResponse')
        relay_state = request.form.get('RelayState', '/admin')

        if not saml_response:
            return render_template('error.html', error='No SAML response received'), 400

        parser = SAMLResponseParser(
            saml_response, 
            IDP_CERT,
            validate_time=saml_config.validate_time,
            validate_audience=saml_config.validate_audience,
            expected_audience=SP_ENTITY_ID,
            validate_destination=saml_config.validate_destination,
            expected_destination=SP_ACS_URL,
            time_tolerance=saml_config.time_tolerance
        )

        if not parser.is_valid():
            return render_template('error.html', error='SAML response validation failed'), 401

        assertion_ids = parser.get_assertion_ids()
        for assertion_id in assertion_ids:
            if assertion_id in processed_assertion_ids:
                return render_template('error.html', error='Replay attack detected'), 401
            processed_assertion_ids.add(assertion_id)

        nameid = parser.get_nameid()

        if not nameid:
            return render_template('error.html', error='Unable to get user identifier'), 401

        session['email'] = nameid

        return redirect(url_for('admin'))

    except Exception as e:
        return render_template('error.html', error=f'Error processing SAML response: {str(e)}'), 500


@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('index'))


@app.route('/admin')
def admin():
    if 'email' not in session:
        return redirect(url_for('saml_login'))

    if session.get('email') != 'admin@rois.team':
        return render_template('error.html', error='Insufficient permissions, admin access only'), 403

    return render_template_string(os.getenv("FLAG","RCTF{test_flag}"))


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=26000, debug=False)

const express = require('express');
const router = express.Router();
const { body } = require('express-validator');
const AuthController = require('../controllers/authController');
const { requireAuth, redirectIfAuthenticated } = require('../middleware/auth');

const registerValidation = [
    body('username')
        .trim()
        .isLength({ min: 3, max: 50 })
        .withMessage('Username must be between 3-50 characters')
        .matches(/^[a-zA-Z0-9_]+$/)
        .withMessage('Username can only contain letters, numbers, and underscores'),

    body('email')
        .trim()
        .isEmail()
        .withMessage('Please enter a valid email address')
        .normalizeEmail(),

    body('password')
        .isLength({ min: 6 })
        .withMessage('Password must be at least 6 characters'),

    body('confirmPassword')
        .custom((value, { req }) => value === req.body.password)
        .withMessage('Passwords do not match'),

    body('type'),

    body('invitationCode')
        .if(body('type').equals('0'))
        .notEmpty()
        .withMessage('Invited users must provide an invitation code')
];

const loginValidation = [
    body('username')
        .trim()
        .notEmpty()
        .withMessage('Please enter username'),

    body('password')
        .notEmpty()
        .withMessage('Please enter password')
];

router.get('/register', redirectIfAuthenticated, AuthController.showRegister);

router.post('/register', redirectIfAuthenticated, registerValidation, AuthController.register);

router.get('/login', redirectIfAuthenticated, AuthController.showLogin);

router.post('/login', redirectIfAuthenticated, loginValidation, AuthController.login);

router.get('/logout', AuthController.logout);
router.post('/logout', AuthController.logout);

router.get('/api/me', requireAuth, AuthController.getCurrentUser);

module.exports = router;

